{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A gentle aromatherapy practice that may support calm, rest, and focus. Guided exercises, tailored blends, and an approachable boutique.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="services.html">Offerings</a>
        <a href="blends.html">Custom Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Plans</a>
        <a href="about.html">About</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="header-actions">
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button id="try-now" class="btn ghost">Try it now</button>
      </div>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal" data-reveal>
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="lead">An approachable aromatherapy practice that may support quiet focus, restful evenings, and clearer intention. Small rituals you can return to anytime.</p>
          <p class="meta">Local to {{CITY}}, {{STATE}} · Call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button id="try-now-hero" class="btn ghost">Try a micro ritual</button>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg class="pattern" width="400" height="300" viewBox="0 0 400 300" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <pattern id="p" patternUnits="userSpaceOnUse" width="40" height="40">
                <rect width="40" height="40" fill="#f7f2ee"></rect>
                <path d="M0 20 Q10 10 20 20 T40 20" stroke="#e4d9c8" stroke-width="2" fill="none"/>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)"></rect>
          </svg>
        </div>
      </div>
    </section>

    <!-- Our Story -->
    <section class="story reveal" data-reveal>
      <div class="wrap">
        <h2>Why we do this</h2>
        <p>We blend simple rituals with plant aromatics so you have gentle practices to return to. Each offering is designed to be practical, safe, and supportive — not a replacement for medical care but a companion for everyday rhythms.</p>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework reveal" data-reveal>
      <div class="wrap">
        <h2>How it works</h2>
        <ol class="steps">
          <li><strong>Consult:</strong> A short conversation to learn preferences, sensitivities, and safety considerations (pets, pregnancy, medications).</li>
          <li><strong>Design:</strong> A suggested ritual or blend that may support your aim — wording uses "may support" and includes a dilution guide.</li>
          <li><strong>Practice:</strong> Micro-exercises and journaling prompts you can use at home.</li>
        </ol>
        <p class="safety">Safety: We advise patch testing, careful dilution, and avoiding certain oils during pregnancy or with pets. See the FAQ for details.</p>
      </div>
    </section>

    <!-- Offers -->
    <section class="offers reveal" data-reveal>
      <div class="wrap grid">
        <div class="card">
          <h3>Intro Session</h3>
          <p>A 45-minute consultation and a take-home sample blend. May support daily calm and clearer focus.</p>
          <p class="price">$75</p>
          <a class="btn" href="book.html">Book Intro</a>
        </div>
        <div class="card">
          <h3>Rhythm Session</h3>
          <p>A 90-minute session with a custom ritual plan and two follow-up notes by email.</p>
          <p class="price">$150</p>
          <a class="btn" href="book.html">Plan a Rhythm</a>
        </div>
        <div class="card">
          <h3>At-Home Blend</h3>
          <p>We formulate a personalized 10ml blend with safety guidance and dilution instructions.</p>
          <p class="price">$35 + shipping</p>
          <a class="btn" href="blends.html">Order Blend</a>
        </div>
      </div>
    </section>

    <!-- Pricing summary -->
    <section class="pricing reveal" data-reveal>
      <div class="wrap">
        <h2>Plans &amp; Packs</h2>
        <p>Pick a rhythm that fits you. Subscriptions are framed as supportive packs rather than commitments — pause anytime.</p>
        <ul class="pricing-list">
          <li><strong>Starter Pack</strong> — One session + sample blend — $95</li>
          <li><strong>Support Pack</strong> — Quarterly check-ins + blends — $330/quarter</li>
          <li><strong>Care Bundle</strong> — Three sessions and seasonal blends — $420</li>
        </ul>
      </div>
    </section>

    <!-- Testimonials -->
    <section class="testimonials reveal" data-reveal>
      <div class="wrap">
        <h2>Notes from people</h2>
        <blockquote>"A small set of practices I actually keep coming back to. The blends are gentle and well-explained." — R.</blockquote>
        <blockquote>"Clear guidance, practical dilution instructions, and great follow-up." — M.</blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta reveal" data-reveal>
      <div class="wrap cta-box">
        <h2>Ready to set a small intention?</h2>
        <p>Book a conversation or try a guided micro-exercise now — it takes under five minutes.</p>
        <div class="cta-actions">
          <a class="btn primary" href="book.html">Begin with a chat</a>
          <button id="try-now-cta" class="btn ghost">Try micro ritual</button>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <div>
        <nav class="footer-nav">
          <a href="about.html">Our Approach</a>
          <a href="pricing.html">Plans</a>
          <a href="contact.html">Contact</a>
        </nav>
      </div>
      <div>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p><a href="robots.txt">Robots</a> · <a href="sitemap.xml">Sitemap</a></p>
      </div>
    </div>
  </footer>

  <!-- Guided modal -->
  <div id="guided-modal" class="modal" aria-hidden="true" role="dialog" aria-labelledby="guided-title">
    <div class="modal-shell">
      <button class="modal-close" id="guided-close" aria-label="Close">✕</button>
      <h3 id="guided-title">Try a 3-step micro ritual</h3>
      <div id="guided-content">
        <div id="guided-step" class="step">Ready to begin?</div>
        <div class="guide-controls">
          <button id="guided-start" class="btn primary">Start</button>
          <button id="guided-cancel" class="btn ghost">Cancel</button>
        </div>
        <div id="guided-progress" class="progress" aria-hidden="true">
          <div id="progress-bar" class="bar"></div>
          <div id="progress-text" class="progress-text"></div>
        </div>
        <div id="guided-journal" class="journal" aria-hidden="true">
          <label for="journal-entry">A quick prompt: What would help you feel steadier today?</label>
          <textarea id="journal-entry" rows="4" placeholder="Write one or two sentences..."></textarea>
          <div class="journal-actions">
            <button id="journal-save" class="btn primary">Save</button>
            <button id="journal-skip" class="btn ghost">Skip</button>
          </div>
        </div>
        <p class="disclaimer">This exercise is a short mindful practice and not medical care. If you have health concerns, consult a professional. See our FAQ for patch test and dilution guidance.</p>
      </div>
    </div>
  </div>

  <div id="overlay" class="overlay" hidden></div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
