{"path":"assets/css/styles.css","content":"/* Core styles for aromatherapy site */
:root{--bg:#fbf7f2;--muted:#7a6b5f;--accent:#b98f6b;--accent-2:#c7b59a;--card:#fff;--shadow:rgba(24,20,18,0.06)}
*{box-sizing:border-box}
html,body{height:100%}
body.theme{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#2b2b2b;background:var(--bg);}
.wrap{max-width:1060px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(4px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:#2b2b2b;text-decoration:none;font-size:1.12rem}
.nav{display:flex;gap:12px;margin-left:12px}
.nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:6px}
.nav a:hover{background:rgba(0,0,0,0.03)}
.header-actions{margin-left:auto;display:flex;gap:8px}
.btn{border:1px solid transparent;padding:8px 12px;border-radius:8px;font-weight:600;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border-color:transparent}
.btn.ghost{background:transparent;border-color:rgba(0,0,0,0.06)}
.hero{padding:48px 0;background-image:url('/assets/img/pattern.svg');background-repeat:repeat}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:center}
.lead{font-size:1.05rem;color:var(--muted)}
.hero-visual svg{max-width:100%;border-radius:12px;box-shadow:0 6px 20px var(--shadow)}
.section{padding:48px 0}
.story .wrap, .framework .wrap{background:linear-gradient(180deg,#fff,rgba(255,255,255,0.9));border-radius:10px;padding:28px;box-shadow:0 6px 18px var(--shadow)}
.steps{padding-left:18px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}
.card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 10px 24px var(--shadow)}
.price{font-weight:700;color:var(--accent);margin-top:8px}
.pricing-list{list-style:none;padding-left:0}
.testimonials blockquote{background:#fff;padding:16px;border-radius:8px;box-shadow:0 6px 18px var(--shadow);margin-bottom:12px}
.cta-box{display:flex;flex-direction:column;align-items:flex-start;gap:12px;padding:24px;border-radius:12px;background:linear-gradient(90deg,#fff,#fbfbfa);box-shadow:0 8px 30px var(--shadow)}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;padding:28px 0}
.footer-nav a{display:block;color:var(--muted);text-decoration:none;padding:4px 0}
.safety{font-size:0.9rem;color:var(--muted);margin-top:12px}

/* Modal */
.modal{position:fixed;inset:10vh 12px 10vh 12px;display:flex;align-items:center;justify-content:center;z-index:60}
.modal-shell{background:#fff;padding:20px;border-radius:12px;max-width:640px;width:100%;box-shadow:0 20px 60px rgba(16,12,8,0.35)}
.modal-close{position:absolute;right:18px;top:12px;background:transparent;border:0;font-size:18px;cursor:pointer}
.overlay{position:fixed;inset:0;background:rgba(9,8,7,0.38);z-index:50}
.modal .step{font-size:1.05rem;margin-bottom:12px}
.progress{margin-top:12px}
.progress .bar{height:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));width:0;border-radius:8px;transition:width 500ms linear}
.progress-text{font-size:0.9rem;color:var(--muted);margin-top:6px}
.journal{margin-top:12px}
.journal textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}
.journal-actions{display:flex;gap:8px;margin-top:8px}
.disclaimer{font-size:0.8rem;color:var(--muted);margin-top:12px}

/* Reveal states */
.reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms ease,transform 520ms ease}
.reveal.visible{opacity:1;transform:none}

/* Reduced motion */
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none}
  .progress .bar{transition:none}
}

/* Responsive */
@media (max-width:780px){
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  .footer-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utility for prefers-reduced-motion
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Scroll-triggered reveal
  const revealEls = Array.from(document.querySelectorAll('[data-reveal]'));
  function revealOnScroll(entries, obs){
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        entry.target.classList.add('visible');
        obs.unobserve(entry.target);
      }
    });
  }
  if(reduceMotion){
    // If reduced motion, reveal everything immediately
    revealEls.forEach(el=>el.classList.add('visible'));
  } else if('IntersectionObserver' in window){
    const io = new IntersectionObserver(revealOnScroll,{threshold:0.12});
    revealEls.forEach(el=>io.observe(el));
  } else {
    // Fallback
    revealEls.forEach(el=>el.classList.add('visible'));
  }

  // Modal guided exercise
  const modal = document.getElementById('guided-modal');
  const overlay = document.getElementById('overlay');
  const startBtns = [document.getElementById('try-now'), document.getElementById('try-now-hero'), document.getElementById('try-now-cta')].filter(Boolean);
  const guidedStart = document.getElementById('guided-start');
  const guidedClose = document.getElementById('guided-close');
  const guidedCancel = document.getElementById('guided-cancel');
  const stepEl = document.getElementById('guided-step');
  const progressBar = document.getElementById('progress-bar');
  const progressText = document.getElementById('progress-text');
  const guidedProgress = document.getElementById('guided-progress');
  const guidedJournal = document.getElementById('guided-journal');
  const journalSave = document.getElementById('journal-save');
  const journalSkip = document.getElementById('journal-skip');
  const journalEntry = document.getElementById('journal-entry');

  let state = {phase:0, timer:null, elapsed:0, durations:[24,20,10]};
  // phases: 0 intro, 1 breathing, 2 journaling, 3 intention

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    overlay.hidden = false;
    document.body.style.overflow = 'hidden';
    stepEl.textContent = 'Ready to begin?';
    guidedProgress.setAttribute('aria-hidden','true');
    guidedJournal.setAttribute('aria-hidden','true');
    state.phase = 0; state.elapsed = 0;
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    overlay.hidden = true;
    document.body.style.overflow = '';
    clearInterval(state.timer);
    state.timer = null; state.phase = 0; state.elapsed = 0;
    progressBar.style.width = '0%';
    progressText.textContent = '';
    journalEntry.value = '';
  }

  startBtns.forEach(b=>b.addEventListener('click',openModal));
  guidedClose.addEventListener('click',closeModal);
  guidedCancel.addEventListener('click',closeModal);
  overlay.addEventListener('click',closeModal);

  function startBreathing(){
    // Simple timed breathing: inhale 4s, hold 4s, exhale 6s -> cycles until duration
    const duration = state.durations[0]; // seconds
    let sec = 0;
    guidedProgress.setAttribute('aria-hidden','false');
    progressText.textContent = 'Breathing — follow the cues';
    progressBar.style.width = '0%';
    state.timer = setInterval(()=>{
      sec++;
      const pct = Math.min(100, Math.round((sec/duration)*100));
      progressBar.style.width = pct + '%';
      if(sec <= duration){
        // simple cue mapping
        const cycle = sec % 14;
        if(cycle >=1 && cycle <=4) stepEl.textContent = 'Inhale gently (4s)';
        else if(cycle >=5 && cycle <=8) stepEl.textContent = 'Hold (4s)';
        else stepEl.textContent = 'Exhale slowly (6s)';
      }
      if(sec >= duration){
        clearInterval(state.timer);
        state.timer = null;
        nextPhase();
      }
    },1000);
  }

  function startJournaling(){
    state.elapsed = 0;
    const duration = state.durations[1];
    guidedJournal.setAttribute('aria-hidden','false');
    guidedProgress.setAttribute('aria-hidden','false');
    progressText.textContent = 'Journaling — a short prompt';
    stepEl.textContent = 'Write a quick note about how you want to feel';
    progressBar.style.width = '0%';
    state.timer = setInterval(()=>{
      state.elapsed++;
      const pct = Math.min(100, Math.round((state.elapsed/duration)*100));
      progressBar.style.width = pct + '%';
      if(state.elapsed >= duration){
        clearInterval(state.timer);
        state.timer = null;
        nextPhase();
      }
    },1000);
  }

  function startIntention(){
    const duration = state.durations[2];
    guidedJournal.setAttribute('aria-hidden','true');
    guidedProgress.setAttribute('aria-hidden','false');
    stepEl.textContent = 'Set a short intention — repeat it aloud twice';
    progressText.textContent = 'Intention — finish in a few moments';
    progressBar.style.width = '0%';
    let sec=0;
    state.timer = setInterval(()=>{
      sec++;
      const pct = Math.min(100, Math.round((sec/duration)*100));
      progressBar.style.width = pct + '%';
      if(sec >= duration){
        clearInterval(state.timer);
        state.timer = null;
        stepEl.textContent = 'Done — you can close this window or save your note.';
        progressText.textContent = 'Thank you.';
      }
    },1000);
  }

  function nextPhase(){
    state.phase++;
    if(state.phase === 1) startBreathing();
    else if(state.phase === 2) startJournaling();
    else if(state.phase === 3) startIntention();
  }

  guidedStart.addEventListener('click',()=>{
    if(reduceMotion){
      // If reduced motion prefer shorter runs
      state.durations = [12,8,6];
    }
    // begin with breathing phase
    state.phase = 1;
    startBreathing();
  });

  journalSave.addEventListener('click',()=>{
    const txt = journalEntry.value.trim();
    if(txt) {
      // store locally for a few minutes (no backend)
      try{ localStorage.setItem('aroma_journal_last',JSON.stringify({text:txt,at:Date.now()})); } catch(e){}
    }
    // proceed to intention
    if(state.timer){ clearInterval(state.timer); state.timer = null; }
    nextPhase();
  });
  journalSkip.addEventListener('click',()=>{
    if(state.timer){ clearInterval(state.timer); state.timer = null; }
    nextPhase();
  });

  // Keyboard escape to close
  document.addEventListener('keydown', (e)=>{
    if(e.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') closeModal();
  });

  // Accessibility: focus trap basics
  modal.addEventListener('keydown', function(e){
    if(e.key!=='Tab') return;
    const focusable = modal.querySelectorAll('button, [href], input, textarea, [tabindex]:not([tabindex="-1"])');
    if(focusable.length===0) return;
    const first = focusable[0]; const last = focusable[focusable.length-1];
    if(e.shiftKey && document.activeElement === first){ last.focus(); e.preventDefault(); }
    else if(!e.shiftKey && document.activeElement === last){ first.focus(); e.preventDefault(); }
  });

})();"} 
